<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { amountInput, yuanInput, lineKinds, artistServiceKinds, isSpecification, type SpecData, type Specification } from '@/api/modules/trade'
import { isWorkingCalendar } from '@/api/modules/customizationDelivery'
import { validSupplyId } from '@/api/modules/supply'
import CopyrightChoice from './CopyrightChoice.vue'
import { commercialUses, type CopyrightTerms } from '@/api/modules/rights'
const copyright=ref<CopyrightTerms|null>(null)
const props=defineProps<{disabled:boolean;previous?:string;provider?:string;providerName?:string}>(),emit=defineEmits<{submit:[body:Omit<SpecData,'review'>&{previous_spec_id:string|null}]}>()
const f=reactive({title:'',provider:'',kind:'',price:'',tier:'',version:'',sample:'',final:'',revisions:'',deliverables:'',terms:'',previous:props.previous||'',serviceKind:'',rule:'',source:'',retry:'',months:'',halo:'',deliveryVersion:'',deliverySource:'',acceptance:'',cancellation:'',calendarVersion:'',calendarSource:'',calendarFrom:'',calendarUntil:'',nonWorking:'',working:'',stockScope:'',stockTerritory:'',stockFrom:'',stockUntil:'',stockUses:[] as string[]})
const custom=computed(()=>['PRIVATE_CUSTOMIZATION','MANUAL_SAMPLE'].includes(f.serviceKind))
watch(custom,v=>{if(v)f.kind='PRODUCTION'})
const stock=computed(()=>f.serviceKind==='STOCK_VIDEO')
watch(()=>props.provider,v=>{if(stock.value)f.provider=v||''})
watch(stock,v=>{if(v){f.kind='OTHER';f.provider=props.provider||f.provider}})
const artist=computed(()=>Object.hasOwn(artistServiceKinds,f.serviceKind))
const body=computed(()=>{
 if(custom.value&&!copyright.value||stock.value&&!f.stockScope)return null
 const iso=(v:string)=>v&&Number.isFinite(Date.parse(v))?new Date(v).toISOString():''
 const dates=(v:string)=>v.split(/[\s,，]+/).filter(Boolean)
 const calendar={version:f.calendarVersion.trim(),source_ref:f.calendarSource.trim(),timezone:'Asia/Shanghai' as const,valid_from:f.calendarFrom,valid_until:f.calendarUntil,non_working_dates:dates(f.nonWorking),working_dates:dates(f.working)}
 if(f.serviceKind==='PRIVATE_CUSTOMIZATION'&&!isWorkingCalendar(calendar))return null
 const unit=artist.value||stock.value?yuanInput(f.price):amountInput(f.price),deliverables=f.deliverables.split('\n').map(s=>s.trim()).filter(Boolean)
 const shared={version:f.version.trim(),service_tier:f.tier.trim(),deliverables,terms:f.terms.trim()}
 let specification:unknown
 if(stock.value)specification={version:f.version.trim(),stock_license:{exclusive:false,acceptance_hours:amountInput(f.acceptance,1,720),aftercare_terms:f.cancellation.trim(),...(f.stockScope==='COMMERCIAL_LIMITED'?{scope:'COMMERCIAL_LIMITED',territory:f.stockTerritory.trim(),duration:'FIXED_TERM',personal_social_sharing:false,commercial_uses:[...f.stockUses],valid_from:iso(f.stockFrom),valid_until:iso(f.stockUntil)}:{scope:'PERSONAL_NONCOMMERCIAL',territory:'WORLDWIDE',duration:'PERPETUAL',personal_social_sharing:true})},terms:f.terms.trim()}
 else if(artist.value)specification={...shared,service:{kind:f.serviceKind,unit:f.serviceKind==='AVATAR_CREATION'?'PERSON_FIRST':f.serviceKind==='AVATAR_HOSTING'?'AVATAR_MONTH':'HALO_APPLICATION',rule_version:f.rule.trim(),source_ref:f.source.trim(),retry_limit:f.serviceKind==='AVATAR_CREATION'?amountInput(f.retry,0,100):0,hosting_months:f.serviceKind==='AVATAR_HOSTING'?amountInput(f.months,1,120):null,halo_level:f.serviceKind==='HALO_REVIEW'?amountInput(f.halo,2,2):null,failure_policy:'REFUND_UNDELIVERED'}}
 else specification={...shared,...(custom.value?{copyright_terms:copyright.value}:{}),sample_seconds:amountInput(f.sample,0,100000),final_seconds:amountInput(f.final,0,100000),revision_limit:amountInput(f.revisions,0,100000),...custom.value?{customization_delivery:{version:f.deliveryVersion.trim(),source_ref:f.deliverySource.trim(),preview_payment_order:f.serviceKind==='MANUAL_SAMPLE'?'PREVIEW_BEFORE_INTERIM':'SCRIPT_BEFORE_INTERIM',acceptance_hours:f.serviceKind==='PRIVATE_CUSTOMIZATION'?null:amountInput(f.acceptance,1,720),...(f.serviceKind==='PRIVATE_CUSTOMIZATION'?{acceptance_working_days:5,acceptance_calendar:calendar}:{}),cancellation_terms:f.cancellation.trim()}}:{}}
 if(!f.title.trim()||!validSupplyId(f.provider)||!artist.value&&!Object.hasOwn(lineKinds,f.kind)||unit===null||!isSpecification(specification)||new Set(deliverables).size!==deliverables.length||f.previous&&!validSupplyId(f.previous))return null
 return {title:f.title.trim(),provider_party_id:f.provider,line_kind:artist.value||stock.value?'OTHER' as const:custom.value?'PRODUCTION' as const:f.kind as keyof typeof lineKinds,unit_minor:unit,currency:'CNY' as const,specification:specification as Specification,previous_spec_id:f.previous||null,...artist.value||custom.value||stock.value?{product_profile:{version:'V5' as const,type:f.serviceKind as keyof typeof artistServiceKinds|'PRIVATE_CUSTOMIZATION'|'MANUAL_SAMPLE'|'STOCK_VIDEO'}}:{}}
})
</script>
<template><form class="trade-form" @submit.prevent="body && emit('submit',body)"><fieldset :disabled="disabled">
 <section class="supply-card"><h2>服务对象</h2><label>商品类别<select v-model="f.serviceKind" data-testid="trade-spec-service-kind"><option value="">影视制作与许可（既有业务）</option><option value="STOCK_VIDEO">V5 现货许可（个人或独立商用）</option><option value="PRIVATE_CUSTOMIZATION">V5 私人定制</option><option value="MANUAL_SAMPLE">V5 人工样片</option><option v-for="(label,key) in artistServiceKinds" :key="key" :value="key">{{label}}</option></select></label><p v-if="artist" class="muted">只填写该服务的实际约定。认证费不保证通过；档案交付与长期模型训练分别核对。</p></section>
 <section class="supply-card"><h2>商品信息</h2><div class="trade-fields two"><label>商品名称 *<input v-model="f.title" maxlength="200" required placeholder="待填写"></label><label v-if="stock">实际提供方<output>{{providerName||'当前办理主体'}}</output></label><label v-else>实际提供方主体编号 *<input v-model="f.provider" required placeholder="完整主体编号"></label></div></section>
 <section class="supply-card"><h2>服务与计价</h2><div class="trade-fields four"><label v-if="!artist">服务明细类型 *<select v-model="f.kind" :disabled="custom||stock" required><option value="">待选择</option><option v-for="(name,key) in lineKinds" :key="key" :value="key">{{name}}</option></select></label><label>{{artist||stock?'服务单价（元） *':'服务单价（人民币分） *'}}<input v-model="f.price" :inputmode="artist||stock?'decimal':'numeric'" required :placeholder="artist?'明确费用，最多两位小数':'整数分'"></label><label>币种<input value="人民币 CNY" disabled></label><label v-if="!stock">服务档位 *<input v-model="f.tier" maxlength="100" required placeholder="待填写"></label></div></section>
 <section class="supply-card"><h2>规格参数</h2><div class="trade-fields four"><label>规格版本 *<input v-model="f.version" maxlength="128" required placeholder="待填写"></label><template v-if="!artist&&!stock"><label>样片时长（秒） *<input v-model="f.sample" inputmode="numeric" required placeholder="明确填写，含 0"></label><label>成片时长（秒） *<input v-model="f.final" inputmode="numeric" required placeholder="明确填写，含 0"></label><label>可修改次数 *<input v-model="f.revisions" inputmode="numeric" required placeholder="明确填写，含 0"></label></template><template v-else-if="artist"><label>服务规则版本 *<input v-model="f.rule" maxlength="128" required></label><label>规则来源 *<input v-model="f.source" maxlength="128" required></label><label v-if="f.serviceKind==='AVATAR_CREATION'">约定重试次数 *<input v-model="f.retry" inputmode="numeric" required placeholder="0—100，按实际约定"></label><label v-if="f.serviceKind==='AVATAR_HOSTING'">约定托管月数 *<input v-model="f.months" inputmode="numeric" required placeholder="1—120，按实际约定"></label><label v-if="f.serviceKind==='HALO_REVIEW'">审核等级 *<select v-model="f.halo" required><option value="">待选择</option><option value="2">L2认证审核</option><option disabled>L3本轮不可购买</option></select></label></template></div><p v-if="artist" class="muted">未交付部分按原订单办理退款；首次核实收款后起算，续期接已有期限，实际日期以服务记录为准，续期提醒不是自动扣款。</p></section>
 <CopyrightChoice v-if="custom" v-model="copyright" :sample="f.serviceKind==='MANUAL_SAMPLE'"/><section v-if="stock" class="supply-card"><h2>现货许可与售后</h2><label>本次商品许可 *<select v-model="f.stockScope" required><option value="">请主动选择</option><option value="PERSONAL_NONCOMMERCIAL">个人非商用</option><option value="COMMERCIAL_LIMITED">独立商用（新售须另行开启）</option></select></label><template v-if="f.stockScope==='COMMERCIAL_LIMITED'"><label>商用地域 *<input v-model="f.stockTerritory" maxlength="100" required></label><label>许可开始（本地时间） *<input v-model="f.stockFrom" type="datetime-local" required></label><label>许可截止（本地时间） *<input v-model="f.stockUntil" type="datetime-local" required></label><div class="license-checks"><label v-for="(label,key) in commercialUses" :key="key"><input v-model="f.stockUses" type="checkbox" :value="key">{{label}}</label></div><p>仅限本单买受人、非独家，固定期间；不包含转售、再许可、改编、发行、训练、源文件或版权买断。价格按本商品明确填写，不沿用示例价。</p></template><p v-else>个人许可非独家、全球、永久、非商用，允许个人收藏和社交分享，不包含广告、改编或发行。</p><label>明确收讫后验收小时数<input v-model="f.acceptance" inputmode="numeric" required></label><label>实际售后约定<textarea v-model="f.cancellation" maxlength="8000" required></textarea></label></section><section v-if="custom" class="supply-card" data-testid="trade-spec-delivery"><h2>定制履约约定</h2><div class="trade-fields two"><label>履约规则版本 *<input v-model="f.deliveryVersion" maxlength="128" required></label><label>原约定来源 *<input v-model="f.deliverySource" maxlength="128" required></label><template v-if="f.serviceKind==='PRIVATE_CUSTOMIZATION'"><p>最终成片确认收到后5个工作日，按北京时间及本单保存的日历；脚本、样片和粗剪由客户明确确认。</p><label>日历版本 *<input v-model="f.calendarVersion" maxlength="128" required></label><label>日历来源依据 *<input v-model="f.calendarSource" maxlength="128" required></label><label>日历有效起日 *<input v-model="f.calendarFrom" type="date" required></label><label>日历有效止日 *<input v-model="f.calendarUntil" type="date" required></label><label>节假日休息日期<textarea v-model="f.nonWorking" placeholder="每行一个年-月-日；按实际公告填写"></textarea></label><label>周末调休工作日期<textarea v-model="f.working" placeholder="每行一个年-月-日；没有则留空"></textarea></label></template><label v-else>明确收讫后确认期限（小时） *<input v-model="f.acceptance" inputmode="numeric" required placeholder="1—720，按实际约定"></label><label>取消、保留金额与退款约定 *<textarea v-model="f.cancellation" maxlength="8000" required></textarea></label></div><p class="muted">{{f.serviceKind==='MANUAL_SAMPLE'?'人工样片采用自身两期约定。':'私人定制采用脚本确认中款的30/40/30及5工作日约定。日历来源与日期须由独立审核人核对；发布新规格不代表全站已切换。'}}规则、费用和取消条款独立审核后保存，新规格不改写历史订单。</p></section>
 <section class="supply-card"><h2>交付与条款</h2><div class="trade-fields two"><label v-if="!stock">约定交付内容 *<textarea v-model="f.deliverables" required placeholder="每行一项，最多 30 项"></textarea></label><label>完整条款 *<textarea v-model="f.terms" maxlength="8000" required placeholder="待填写"></textarea></label></div></section>
 <section class="supply-card"><h2>历史版本关联</h2><p v-if="stock">{{previous?'沿已读取的上一商品创建新版本。':'首次登记当前商品；已有版本可从原商品进入更新。'}}</p><label v-else class="trade-inline">上一商品版本<input v-model="f.previous" placeholder="首次创建留空；新版本填写原记录编号"></label><p class="muted">新版本独立审核；价格、规格和条款不会改写历史订单。</p></section>
 <div class="trade-footer"><RouterLink to="/trade/specifications" class="button-link outline">返回商品</RouterLink><button class="primary" :disabled="disabled || !body">提交规格审核</button></div>
 </fieldset></form></template>
